do $patch_v5_guided_step_visual_stimulus$
declare
  function_definition text;
  old_clause text := '''position'', item.position';
  new_clause text := '''position'', item.position, ''visual_stimulus'', question.metadata->''visual_stimulus''';
  occurrence_count integer;
begin
  select pg_get_functiondef('public.get_guided_learning_step_v4(uuid)'::regprocedure)
    into function_definition;
  if function_definition is null then raise exception 'V5_VISUAL_STEP_FUNCTION_MISSING'; end if;
  if position(new_clause in function_definition) > 0 then return; end if;
  select (length(function_definition)-length(replace(function_definition, old_clause, '')))/length(old_clause)
    into occurrence_count;
  if occurrence_count <> 1 then raise exception 'V5_VISUAL_STEP_PATCH_MISMATCH'; end if;
  execute replace(function_definition, old_clause, new_clause);
end;
$patch_v5_guided_step_visual_stimulus$;


-- Authorial V5 content is compiled for review but remains inactive and unaligned.
-- No student can receive it until separate pedagogical and publication gates pass.
do $seed_question_first_content_v5$
declare
  v_catalog_id uuid;
  v_skill_id uuid;
  v_lesson_id uuid;
  v_set_id uuid;
  v_question_id uuid;
  v_question record;
begin
  select id into v_catalog_id
    from public.learning_curriculum_catalogs
   where code = 'TECESCOLA_CORE' and version = '1.0'
   limit 1;
  if v_catalog_id is null then raise exception 'V5_CONTENT_CATALOG_MISSING'; end if;
  select id into v_skill_id
    from public.learning_curriculum_skills
   where catalog_id = v_catalog_id and code = 'ART_INTERPRET_WORK';
  if v_skill_id is null then raise exception 'V5_CONTENT_SKILL_MISSING'; end if;

  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 7, 'Interpretar uma obra com evidências', 'Comece pelo que está presente. Observe como os elementos se relacionam e só então proponha uma leitura que possa ser sustentada por detalhes da obra ou por fontes identificadas.', '## 1. Descreva antes de interpretar
Nomeie o que pode ser observado: cores, linhas, formas, textura, escala, posição, materiais, luz, enquadramento e espaço vazio. Uma descrição não precisa adivinhar tema, autoria ou emoção. Se houver imagem, consulte também a descrição alternativa: ela comunica os elementos essenciais para quem não a percebe visualmente.

## 2. Analise relações
Pergunte como os elementos se organizam. Contraste pode destacar uma forma; repetição e intervalo podem criar ritmo; escala e posição podem estabelecer hierarquia; figura e fundo podem permitir leituras alternadas. Esses são efeitos possíveis da composição, não garantias de reação idêntica.

## 3. Formule uma interpretação sustentada
Use uma sequência curta: “observo ___; noto que ___; isso pode sugerir ___ porque ___”. A frase “pode sugerir” marca uma hipótese. Uma leitura fica mais forte quando relaciona evidência observável e interpretação, sem atribuir uma intenção íntima sem fonte.

## 4. Compare com critérios consistentes
Ao comparar obras, escolha os mesmos critérios para ambas: contraste, escala, repetição, enquadramento, material ou posição. Dizer que duas obras tratam do mesmo tema não significa que tenham a mesma composição.

## 5. Delimite o que não se sabe
Uma imagem recortada não revela o que ficou fora do quadro. Material não comprova sozinho a biografia de quem criou a obra. Uma legenda sustenta apenas os dados que registra. Contexto histórico e relatos de artistas podem ampliar a leitura, mas devem ser identificados como fontes, não confundidos com observações visuais.

## Acessibilidade
Em uma questão visual, a descrição alternativa deve indicar forma, posição, contraste, repetição e outros detalhes relevantes à resposta. O enunciado e o texto alternativo precisam oferecer evidência equivalente, sem depender apenas de cor; quando a informação cromática importa, combine-a com posição, forma ou contraste. O estudante pode ampliar a imagem e usar leitura por voz. Para atividades abertas, aceite resposta por texto, áudio ou descrição oral, sem reduzir o critério de evidência.',
    'Em uma imagem, um círculo vermelho pequeno está isolado perto da borda, enquanto formas cinzentas maiores se agrupam no centro. Observação: há contraste de cor, diferença de escala e separação espacial. Relação: o isolamento e o contraste fazem o círculo chamar atenção. Interpretação possível: ele pode ser percebido como elemento deslocado. Limite: a imagem, sozinha, não identifica uma pessoa nem comprova o que a pessoa artista pretendia representar.', array['Aponte um detalhe concreto antes de escolher uma interpretação.', 'Compare as obras usando os mesmos critérios.', 'Use “pode” para efeitos possíveis e indique o que exigiria uma fonte adicional.']::text[], 28, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-art-interpret-work-evidence-sequence","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Reconhecer cores, formas, linhas e posições em composições simples.","Distinguir observação de uma hipótese de significado."],"key_concepts":["descrição e inferência","contraste e figura-fundo","escala, posição e hierarquia","repetição, intervalo e ritmo","material e técnica","evidência e limite interpretativo","acessibilidade visual"],"progression":[{"stage":"DIAGNOSTIC","focus":"Nomear elementos e separar observação de intenção ou significado não demonstrado.","questionIds":["v5-art-interpret-work-01","v5-art-interpret-work-02","v5-art-interpret-work-03","v5-art-interpret-work-04"]},{"stage":"PRACTICE","focus":"Analisar contraste, escala, espaço, repetição, figura-fundo, paleta, equilíbrio e material.","questionIds":["v5-art-interpret-work-05","v5-art-interpret-work-06","v5-art-interpret-work-07","v5-art-interpret-work-08","v5-art-interpret-work-09","v5-art-interpret-work-10","v5-art-interpret-work-11","v5-art-interpret-work-12","v5-art-interpret-work-13"]},{"stage":"TRANSFER","focus":"Aplicar a análise a cartazes, instalações, pintura, fontes e diferentes enquadramentos.","questionIds":["v5-art-interpret-work-14","v5-art-interpret-work-15","v5-art-interpret-work-16","v5-art-interpret-work-17","v5-art-interpret-work-18"]},{"stage":"CONSOLIDATION","focus":"Escolher evidências, revisar generalizações e sustentar leituras abertas com critérios.","questionIds":["v5-art-interpret-work-19","v5-art-interpret-work-20","v5-art-interpret-work-21"]},{"stage":"REVIEW","focus":"Retomar método, limites de fontes e acesso a evidências visuais.","questionIds":["v5-art-interpret-work-22","v5-art-interpret-work-23","v5-art-interpret-work-24"]}],"micro_explanations":[{"trigger":"OBSERVATION_BEFORE_INTERPRETATION","text":"“Vejo linhas curvas” descreve. “Elas podem sugerir movimento” interpreta e precisa apontar as linhas como evidência."},{"trigger":"RELATION_CREATES_EFFECT","text":"Destaque depende de relações como contraste, posição, escala e espaço; um elemento isolado não explica tudo."},{"trigger":"HYPOTHESIS_NOT_INTENTION","text":"Uma interpretação plausível não comprova a intenção de quem criou a obra. Para isso, é necessária uma fonte identificada."},{"trigger":"IMAGE_CROP_LIMIT","text":"O que não aparece no enquadramento continua desconhecido; ausência na imagem não prova ausência na situação real."},{"trigger":"ACCESSIBLE_VISUAL_EVIDENCE","text":"A descrição alternativa deve fornecer os detalhes visuais usados na resposta, sem depender apenas da percepção de cor."}],"remediations":[{"id":"DESCRIBE_THEN_INFER","misconception":"Atribuir significado específico a uma forma isolada.","prompt":"Complete duas frases: “Na obra, observo ___.” e “Isso pode sugerir ___ porque ___.” Se a segunda frase não aponta evidência, reveja a interpretação."},{"id":"COMPARE_SAME_CRITERIA","misconception":"Compara duas obras usando critérios diferentes.","prompt":"Monte duas colunas e use o mesmo critério nas duas: escala, contraste, repetição ou posição. Depois descreva a diferença observada."},{"id":"SOURCE_SCOPE","misconception":"Deduzir intenção ou biografia sem fonte.","prompt":"Sublinhe o que a imagem mostra e circule o que a legenda afirma. Tudo o que não aparece em nenhum dos dois precisa de outra fonte ou deve ficar como hipótese."},{"id":"CROP_AND_UNKNOWN","misconception":"Supor que o enquadramento contém toda a situação.","prompt":"Liste os elementos visíveis e, separadamente, duas informações que ficaram fora do quadro. Não use essas lacunas como fatos."},{"id":"ACCESSIBLE_DESCRIPTION","misconception":"A descrição visual não oferece a mesma evidência.","prompt":"Reescreva a descrição indicando forma, posição, contraste e relação espacial; se cor for relevante, associe-a a outro atributo perceptível."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"publisher":"J. Paul Getty Museum, Education","title":"Understanding Formal Analysis","url":"https://www.getty.edu/education/teachers/classroom_resources/formal_analysis.html","license":"Referência de método de análise; as obras, ilustrações e questões deste pacote são autorais."},{"publisher":"Ministério da Educação, Brasil","title":"Base Nacional Comum Curricular","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","license":"Referência curricular geral; não há reivindicação de mapeamento oficial específico neste pacote."}],"copyright_note":"Textos, questões e ilustrações SVG originais deste pacote. Sem imagens de terceiros. O vínculo curricular oficial e a revisão pedagógica humana permanecem pendentes.","authentic_activities":[{"id":"ART_OBSERVE_RELATE_INTERPRET","title":"Ver, relacionar e interpretar","objective":"Produzir uma leitura visual sustentada por evidências, distinguindo descrição, interpretação e informação ainda desconhecida.","instructions":"Escolha uma ilustração autoral deste percurso ou uma obra indicada pelo professor. Registre três detalhes observáveis; explique uma relação entre eles; proponha uma interpretação usando “pode sugerir” e cite os detalhes que a sustentam. Termine anotando uma conclusão que a imagem sozinha não permite afirmar.","evidence":"Apresentar uma resposta escrita, em áudio ou oral com três observações, uma relação composicional, uma interpretação apoiada e um limite explicitado.","privacyGuard":"Use apenas imagens fornecidas ou autorizadas pelo professor. Não inclua rostos, dados pessoais, autoria ou biografia não verificada; não atribua uma interpretação a um grupo inteiro.","rubric":[{"criterion":"Observação visual","emerging":"Nomeia um elemento sem localizá-lo ou descreve algo não visível.","developing":"Descreve dois elementos identificáveis, mas com poucos detalhes espaciais.","proficient":"Descreve três ou mais elementos visíveis com forma, posição, contraste ou relação espacial verificável."},{"criterion":"Interpretação com evidência","emerging":"Apresenta uma conclusão sem apontar elementos que a sustentem.","developing":"Relaciona uma observação a uma leitura possível, mas não explica a relação.","proficient":"Formula uma leitura como hipótese e explica como pelo menos dois detalhes observados a sustentam."},{"criterion":"Limite da conclusão","emerging":"Trata intenção, emoção ou biografia como fato sem fonte.","developing":"Reconhece uma incerteza, mas mistura observação com inferência.","proficient":"Separa observação e hipótese e registra uma informação que exigiria fonte adicional."}]}],"source_question_feedback":[{"questionId":"v3-art-art_interpretation-2","hint":"Primeiro descreva a evidência formal ou material apresentada; depois formule uma leitura possível e explicite o que a imagem ou a fonte não permite concluir.","errorFocus":"OBSERVATION_EVIDENCE_INTERPRETATION_AND_SCOPE"},{"questionId":"v3-art-art_interpretation-4","hint":"Primeiro descreva a evidência formal ou material apresentada; depois formule uma leitura possível e explicite o que a imagem ou a fonte não permite concluir.","errorFocus":"OBSERVATION_EVI